// Comprueba que el aviso lo mandó Clerk (a través de Svix) y que nadie lo cambió en el camino.
// Pasos de la verificación manual de Svix: https://docs.svix.com/receiving/verifying-payloads/how-manual
const crypto = require('crypto');

const config = $('Configuración').first().json;
const pedido = $input.first();
const h = pedido.json.headers ?? {};

// Clerk manda los encabezados svix-*; el estándar Standard Webhooks usa webhook-* (se aceptan los dos).
const id = h['svix-id'] ?? h['webhook-id'];
const timestamp = h['svix-timestamp'] ?? h['webhook-timestamp'];
const firmas = h['svix-signature'] ?? h['webhook-signature'];

const rechazar = (motivo) => [{ json: { firma_valida: false, motivo } }];

if (!id || !timestamp || !firmas) {
  return rechazar('faltan los encabezados svix-id, svix-timestamp o svix-signature');
}

const secreto = String(config.secreto_firma ?? '').trim();
if (!/^whsec_[A-Za-z0-9+/=]{16,}$/.test(secreto)) {
  return rechazar('falta el Signing Secret de Clerk (whsec_...) en el nodo Configuración');
}

// 1. La hora: un aviso viejo puede ser alguien reenviando un pedido que capturó.
const ahora = Math.floor(Date.now() / 1000);
const enviado = Number(timestamp);
const tolerancia = Number(config.tolerancia_segundos ?? 300);
if (!Number.isFinite(enviado) || Math.abs(ahora - enviado) > tolerancia) {
  return rechazar('svix-timestamp está fuera de la tolerancia: el aviso es viejo o la hora no coincide');
}

// 2. El cuerpo tal cual llegó, byte por byte (opción Raw Body del Webhook, binario «data»).
if (!pedido.binary?.data) {
  return rechazar('no llegó el cuerpo crudo: activá Raw Body en las opciones del Webhook');
}
const cuerpo = await this.helpers.getBinaryDataBuffer(0, 'data');

// 3. La firma esperada: HMAC SHA-256 de «id.timestamp.cuerpo».
//    La clave es lo que sigue a whsec_, decodificado de base64.
const clave = Buffer.from(secreto.slice('whsec_'.length), 'base64');
const esperada = crypto.createHmac('sha256', clave).update(`${id}.${timestamp}.`).update(cuerpo).digest();

// 4. svix-signature puede traer varias firmas separadas por espacios («v1,AAA v1,BBB»):
//    alcanza con que una coincida. timingSafeEqual compara sin dar pistas por el tiempo que tarda.
const coincide = String(firmas)
  .split(' ')
  .some((parte) => {
    const [version, firma] = parte.split(',');
    if (version !== 'v1' || !firma) return false;
    const recibida = Buffer.from(firma, 'base64');
    return recibida.length === esperada.length && crypto.timingSafeEqual(recibida, esperada);
  });
if (!coincide) return rechazar('la firma no coincide con el Signing Secret');

// 5. Firma válida: recién ahora se lee el contenido.
let evento;
try {
  evento = JSON.parse(cuerpo.toString('utf8'));
} catch (e) {
  return rechazar('el cuerpo no es JSON');
}

// 6. El perfil con las columnas de la tabla perfiles.
const d = evento.data ?? {};
const correos = Array.isArray(d.email_addresses) ? d.email_addresses : [];
const principal = correos.find((c) => c.id === d.primary_email_address_id) ?? correos[0];
const fecha = (ms) => (typeof ms === 'number' ? new Date(ms).toISOString() : null);

return [
  {
    json: {
      firma_valida: true,
      svix_id: id,
      tipo: evento.type,
      perfil: {
        clerk_id: d.id ?? null,
        email: principal?.email_address ?? null,
        nombre: [d.first_name, d.last_name].filter(Boolean).join(' ') || d.username || null,
        avatar_url: d.image_url ?? null,
        // creado_en y actualizado_en no pueden quedar vacías en la tabla: si faltan, va la hora del evento.
        creado_en: fecha(d.created_at) ?? fecha(evento.timestamp) ?? new Date().toISOString(),
        actualizado_en: fecha(d.updated_at) ?? fecha(evento.timestamp) ?? new Date().toISOString(),
      },
    },
  },
];
